import sys
import math

def is_perfect_square(x):
    s = int(math.sqrt(x))
    return s * s == x

def find_sequence(n, even_elements):
    sequence = [0] * n
    current_sum = 0

    for i in range(0, n, 2):
        if i == 0:
            # Find the smallest x1 such that x1 is a perfect square
            for x1 in range(1, 10**13 + 1):
                if is_perfect_square(current_sum + x1):
                    sequence[i] = x1
                    current_sum += x1
                    break
            else:
                return "No"
        else:
            # Find xi such that current_sum + xi is a perfect square
            found = False
            for xi in range(1, 10**13 + 1):
                    if is_perfect_square(current_sum + xi):
                        sequence[i] = xi
                        current_sum += xi
                        found = True
                        break
            if not found:
                return "No"

        # Add the next even element
        if i + 1 < n:
            sequence[i + 1] = even_elements[(i + 1) // 2]
            current_sum += even_elements[(i + 1) // 2]

    # Check if the final sum is a perfect square
    if not is_perfect_square(current_sum):
        return "No"

    return "Yes\n" + " ".join(map(str, sequence))

input = sys.stdin.read().strip().split('\n')
n = int(input[0])
even_elements = list(map(int, input[1].split()))

result = find_sequence(n, even_elements)
print(result)
